package com.example.examplemod.network;
import com.example.examplemod.CreateCityExpansionCore;
import com.example.examplemod.railway.*;
import net.minecraft.core.BlockPos;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import java.util.*;
public record RailwayRouteOptionsPayload(BlockPos pylonPos,UUID fleetTrainId,String source,String destination,List<RailwayRouteOption> options,String errorKey) implements CustomPacketPayload{
 public static final Type<RailwayRouteOptionsPayload> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(CreateCityExpansionCore.MODID,"railway_route_options"));public static final StreamCodec<RegistryFriendlyByteBuf,RailwayRouteOptionsPayload> STREAM_CODEC=StreamCodec.of(RailwayRouteOptionsPayload::encode,RailwayRouteOptionsPayload::decode);
 public RailwayRouteOptionsPayload{options=List.copyOf(options);source=source==null?"":source;destination=destination==null?"":destination;errorKey=errorKey==null?"":errorKey;}
 private static void encode(RegistryFriendlyByteBuf b,RailwayRouteOptionsPayload p){BlockPos.STREAM_CODEC.encode(b,p.pylonPos);b.writeUUID(p.fleetTrainId);b.writeUtf(p.source,128);b.writeUtf(p.destination,128);b.writeUtf(p.errorKey,64);b.writeVarInt(p.options.size());for(var o:p.options){b.writeUUID(o.id());b.writeEnum(o.strategy());b.writeUUID(o.graphId());b.writeUUID(o.destinationStationId());b.writeBoolean(o.backwards());b.writeDouble(o.distance());b.writeVarLong(o.tariffCost());b.writeVarLong(o.estimatedTicks());b.writeLong(o.topologyFingerprint());b.writeVarInt(o.edges().size());for(var e:o.edges()){node(b,e.first());node(b,e.second());}b.writeVarInt(o.contributions().size());for(var c:o.contributions()){b.writeUUID(c.networkId());b.writeEnum(c.ownerType());b.writeUUID(c.ownerId());b.writeVarLong(c.tariffPerThousandBlocks());b.writeDouble(c.startDistance());b.writeDouble(c.endDistance());b.writeVarLong(c.reservedAmount());}}}
 private static RailwayRouteOptionsPayload decode(RegistryFriendlyByteBuf b){BlockPos pos=BlockPos.STREAM_CODEC.decode(b);UUID train=b.readUUID();String source=b.readUtf(128),destination=b.readUtf(128),error=b.readUtf(64);int count=Math.min(3,b.readVarInt());List<RailwayRouteOption> options=new ArrayList<>();for(int i=0;i<count;i++){UUID id=b.readUUID();var strategy=b.readEnum(RailwayRouteStrategy.class);UUID graph=b.readUUID(),dest=b.readUUID();boolean backwards=b.readBoolean();double distance=b.readDouble();long price=b.readVarLong(),eta=b.readVarLong(),fingerprint=b.readLong();int ec=Math.min(256,b.readVarInt());List<RailwayEdgeReference> edges=new ArrayList<>();for(int j=0;j<ec;j++)edges.add(new RailwayEdgeReference(node(b),node(b)).normalized());int cc=Math.min(256,b.readVarInt());List<RailwayTariffLeg> contributions=new ArrayList<>();for(int j=0;j<cc;j++)contributions.add(new RailwayTariffLeg(b.readUUID(),b.readEnum(RailwayOwnershipTypes.OwnerType.class),b.readUUID(),b.readVarLong(),b.readDouble(),b.readDouble(),b.readVarLong()));options.add(new RailwayRouteOption(id,strategy,graph,dest,backwards,edges,distance,price,eta,contributions,fingerprint));}return new RailwayRouteOptionsPayload(pos,train,source,destination,options,error);}
 private static void node(RegistryFriendlyByteBuf b,RailwayNodeReference n){b.writeResourceLocation(n.dimension());b.writeInt(n.x());b.writeInt(n.y());b.writeInt(n.z());b.writeInt(n.yOffsetPixels());}private static RailwayNodeReference node(RegistryFriendlyByteBuf b){return new RailwayNodeReference(b.readResourceLocation(),b.readInt(),b.readInt(),b.readInt(),b.readInt());}
 public Type<? extends CustomPacketPayload> type(){return TYPE;}
}
